        { name: "Pin Combination (Crucifix)", difficulty: "Advanced", mechanics: "Trap one of opponent's arms between your legs and body, control other arm with your arms, apply pressure to pin opponent's shoulders to mat", grips: "Legs trap opponent's arm, arms control opponent's other arm and head, body weight distributes for maximum pressure", leverage_points: "Trapped arm limits movement, body weight pins shoulders, control of head prevents escape", finish: "Maintain pin with controlled pressure until opponent yields or time expires; transition to submissions or other pins as needed", safety: "Apply pressure gradually and along anatomical lines; avoid crushing joints or ribs; communicate about comfort levels", focus_cues: "Trap arm with legs, control other arm, distribute weight, maintain pressure", anatomy: ["calves", "quadriceps", "core stabilizers", "ankle proprioceptors", "latissimus dorsi", "adductors", "pectorals"] }
