    problemAreaTips: [
      { problem: "Getting Sprawl-On Easily", fix: "Practice keeping head to side during shots; drill penetration steps with partner providing light sprawl resistance; focus on explosive hip drive to finish before opponent can react. Film your shots to identify telegraphing.", difficulty: "Beginner" },
      { problem: "Losing Hand Fights in Clinch", fix: "Drill pummeling daily with focus on elbow position and hip movement; keep hands active and elbows tight; use footwork to create angles that favor your hand fighting. Remember: control the hips, control the clinch.", difficulty: "Intermediate" },
      { problem: "Poor Balance in Neutral Stance", fix: "Practice stance holds with eyes closed to develop proprioception; drill quick direction changes with agility ladder; keep knees bent and weight centered over midfoot. Balance comes from constant micro-adjustments.", difficulty: "Beginner" },
      { problem: "Gasping Out Early in Matches", fix: "Build aerobic base with steady-state cardio; practice breathing techniques during drilling (exhale on effort); pace efforts strategically; avoid wild, wasteful movements. Wrestling is chess at 100mph—breathe to think.", difficulty: "Intermediate" },
      { problem: "Telegraphing Shots", fix: "Practice level changes without dropping shoulders first; use feints to disguise intent; drill shot entries from unexpected angles. Film your shots to identify tells, then eliminate them through slow-motion repetition.", difficulty: "Advanced" },
      { problem: "Getting Stuck in Bad Positions", fix: "Learn one reliable escape per bad position (side control, mount, back); drill that escape daily until automatic; focus on creating space first (frames, shrimping), then executing escape. Stay calm and breathe—panic wastes energy.", difficulty: "Intermediate" },
      { problem: "Poor Mat Awareness", fix: "Practice wrestling near boundaries with coach feedback; use peripheral vision drills; develop spatial awareness through shadow wrestling with boundary markers. Remember: the mat is your battlefield—know its edges.", difficulty: "Beginner" },
      { problem: "Over-Reliance on Strength", fix: "Focus on leverage and positioning over muscle; drill techniques slowly first to ingrain mechanics, add speed later; ask training partners: 'Was that leverage or strength?' Breathe steadily and stay calm to access technique under pressure.", difficulty: "Intermediate" },
      { problem: "Inconsistent Takedown Finishes", fix: "Practice finish mechanics separately from shot entries; drill driving through hips and maintaining pressure until opponent is controlled; use resistance bands to simulate opponent's weight. Finish with intention, not hope.", difficulty: "Intermediate" },
      { problem: "Poor Recovery After Missed Shots", fix: "Drill shot recovery sequences: miss → sprawl defense → reset stance; practice quick footwork to avoid counters; maintain defensive posture even when attacking. Every shot is a commitment—have an exit strategy.", difficulty: "Advanced" }
    ]
